'use strict';
const Scan={basket:new Map(),latest:null,controls:null,generation:0,stop(){this.generation++;this.controls?.stop();this.controls=null;const v=$('scan-video');v?.srcObject?.getTracks().forEach(t=>t.stop());if(v){v.srcObject=null;v.hidden=true;}},async open(){this.stop();this.basket.clear();this.latest=null;Business.open('现场扫描中心',`<p>扫码成功仅表示识别。所有业务变化必须得到服务器确认；二维码不授予权限。</p><form id="scan-form" class="user-form"><div class="form-grid"><label>作业场景<select id="scan-kind"><option value="query">查询与历史</option><option value="stocktake">盘点实盘</option><option value="allocation">客户备货核对</option><option value="load">车辆装车核验</option><option value="move">扫码移库</option><option value="sample">取样选择/核对</option></select></label><label>关联任务<select id="scan-task"><option value="">未指定</option></select></label></div><label>捆包二维码或编号<input id="scan-code" autocomplete="off" autocapitalize="characters" required maxlength="100" placeholder="MSN:BUNDLE:UUID / MSN-CU-..."></label><button class="button primary">联网识别 / 核对</button></form><div class="business-toolbar"><button id="scan-camera" class="button secondary">开启后置相机</button><button id="scan-stop" class="button secondary">停止相机</button><label>识别本地二维码图片<input id="scan-image" type="file" accept="image/png,image/jpeg"></label></div><video id="scan-video" playsinline muted hidden></video><p id="scan-message" role="status"></p><div id="scan-result"></div><h3>已选择捆包（仅本次页面内存）</h3><div id="scan-basket"></div><div class="business-toolbar"><button id="scan-move" class="button secondary">用所选捆包办理移库</button><button id="scan-sample" class="button secondary">用所选捆包新建取样批次</button><button id="scan-clear" class="button secondary">清空选择</button></div>`);$('scan-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await this.resolve($('scan-code').value);}catch(e){this.message(e.message,true);}finally{e.submitter.disabled=false;}};$('scan-kind').onchange=()=>this.tasks().catch(e=>this.message(e.message,true));$('scan-task').onchange=()=>this.reset();$('scan-camera').onclick=()=>this.camera();$('scan-stop').onclick=()=>this.stop();$('scan-image').onchange=e=>this.image(e.target.files[0]);$('scan-clear').onclick=()=>{this.basket.clear();this.renderBasket();};$('scan-move').disabled=!Business.can('move:write');$('scan-sample').disabled=!Business.can('sample:write');$('scan-move').onclick=()=>this.business('move').catch(e=>this.message(e.message,true));$('scan-sample').onclick=()=>this.business('sample').catch(e=>this.message(e.message,true));this.renderBasket();$('dialog').addEventListener('close',()=>this.stop(),{once:true});},message(text,bad=false){if($('scan-message')){$('scan-message').textContent=text;$('scan-message').classList.toggle('error',bad);}},reset(){this.message('请选择任务并重新联网核对');this.latest=null;this.basket.clear();$('scan-result').replaceChildren();this.renderBasket();},async tasks(){this.stop();this.reset();const kind=$('scan-kind').value,route={stocktake:'stocktakes',allocation:'allocations',load:'loads',sample:'samples'}[kind];$('scan-task').replaceChildren(new Option(kind==='sample'?'新建取样批次':'未指定',''));if(route){const r=await API.request('/'+route);for(const x of r.items)$('scan-task').append(new Option(x.code+' · '+(Control.names[x.status]||x.status),x.id));}},async resolve(code){this.latest=null;$('scan-result').replaceChildren();const kind=$('scan-kind').value,id=$('scan-task').value;if(['stocktake','allocation','load'].includes(kind)&&!id)throw Error('请先选择关联任务');const r=await API.request('/scan/resolve',{method:'POST',body:{code,context:{kind:kind==='sample'&&!id?'query':kind,id}}});this.latest=r;const b=r.bundle,m=kind==='stocktake'?await Business.load():null;this.message((r.check.matched?'服务器核对匹配':'服务器核对不匹配')+' · '+r.checked_at+(r.check.duplicate?' · 本轮已盘，禁止在此重复登记':''),!r.check.matched);$('scan-result').innerHTML=`${Control.reportTable([{bundle_no:b.id,physical_weight:b.weight,location:b.location,customer:b.customer,status:b.status}])}<a class="button secondary" href="/stock-map?bundle=${encodeURIComponent(b.id)}">在库存地图定位</a><button id="scan-history" class="button secondary">查看捆包生命周期</button>${kind==='stocktake'?'<form id="scan-count" class="user-form"><label>实盘净重（吨）<input id="scan-actual" required inputmode="decimal"></label><label>实际货位<select id="scan-actual-location">${Business.options(m.locations.filter(x=>x.warehouse_id===b.warehouse_id),b.location_id)}</select></label><label>实盘说明<input id="scan-note" maxlength="500"></label><button class="button primary" id="scan-count-save">提交实盘记录（不调整库存）</button></form>':''}`;$('scan-history').onclick=async()=>{try{this.stop();const h=await API.request('/bundles/'+encodeURIComponent(b.id)+'/history');Business.open('捆包生命周期',Control.reportTable(h.lifecycle)+Control.reportTable(h.events.map(e=>({type:e.event_type,physical_delta:e.physical_delta,created_at:e.occurred_at}))));}catch(e){notify(e.message);}};if(r.check.matched&&!r.check.duplicate)this.basket.set(b.id,b);this.renderBasket();if($('scan-count')){$('scan-count-save').disabled=!r.check.matched||r.check.duplicate||!Business.can('stocktake:write');$('scan-count').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await API.request('/stocktakes/'+id+'/observations',{method:'POST',body:{version:r.check.version,entries:[{bundle_no:b.id,actual_location_id:$('scan-actual-location').value,actual_weight:$('scan-actual').value.trim(),remark:$('scan-note').value}]}});await this.resolve(b.id);this.message('服务器已确认实盘登记；本轮已盘，正式库存未调整');}catch(e){this.message(e.message,true);e.submitter.disabled=false;}};}},renderBasket(){if($('scan-basket'))$('scan-basket').textContent=[...this.basket.keys()].join('、')||'尚未选择';},async decoder(){if(!window.ZXingBrowser)await new Promise((ok,no)=>{const s=document.createElement('script');s.src='/vendor/zxing-browser-0.1.5.min.js';s.onload=ok;s.onerror=()=>no(Error('扫码组件不可用，请手动输入编号'));document.head.append(s);});return new ZXingBrowser.BrowserQRCodeReader();},async camera(){this.stop();if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){this.message('相机需要HTTPS安全环境；当前可手动输入编号',true);return;}const g=this.generation;try{const controls=await QRDecoder.camera($('scan-video'),code=>{if(g!==this.generation)return;this.stop();$('scan-code').value=code;this.resolve(code).catch(e=>this.message(e.message,true));},e=>{this.stop();this.message('无法使用相机，请手动输入编号：'+(e.message||e.name),true);});if(g!==this.generation)controls.stop();else this.controls=controls;}catch(e){this.stop();this.message('无法使用相机，请手动输入编号：'+(e.message||e.name),true);}},async image(file){if(!file)return;if(file.size>5242880){this.message('图片超过5MiB，请手动输入编号',true);return;}try{let code=await QRDecoder.image(file);if(!code){const url=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(file);}),reader=await this.decoder();code=(await reader.decodeFromImageUrl(url)).getText();}if(!code)throw Error('二维码未识别');$('scan-code').value=code;await this.resolve(code);}catch(e){this.message('图片识别失败，请手动输入编号：'+(e.message||'二维码未识别'),true);}},async business(kind){if(!this.basket.size)throw Error('请先联网识别并选择捆包');this.stop();const rows=[...this.basket.values()],first=rows[0],m=await Business.load();Flow.form(kind==='move'?'所选捆包移库确认':'所选捆包取样登记',`<p>捆包：${rows.map(x=>esc(x.id)).join('、')}。提交后由原业务接口再次校验。</p>`+Flow.select('客户','customer_id',m.customers,'name',first.customer_id)+(kind==='move'?Flow.select('目标货位','target_location_id',m.locations.filter(x=>x.active),'code')+Flow.field('移库原因','reason','text','','required'):Flow.field('取样日期','sample_date','date',new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lubumbashi',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),'required')+Flow.field('取样机构','agency','text','','required')),async b=>{const d=await API.request(kind==='move'?'/moves':'/samples',{method:'POST',body:{...b,project_id:first.project_id,bundle_ids:rows.map(x=>x.id)}});this.basket.clear();Business.open('服务器已确认',`<p>${esc(d.code)} · ${esc(Control.names[d.status]||d.status)}。${kind==='move'?'移库不改变库存总重量':'取样登记不扣减实物库存'}。</p>`);});}};
const scanMenu=Business.menu.bind(Business);Business.menu=function(){scanMenu();const b=document.createElement('button');b.className='button primary';b.textContent='现场扫描中心';b.onclick=()=>Scan.open().catch(e=>notify(e.message));document.querySelector('.business-menu').prepend(b);};document.addEventListener('visibilitychange',()=>{if(document.hidden)Scan.stop();});window.addEventListener('session-expired',()=>{Scan.stop();Scan.basket.clear();Scan.latest=null;});
